 let liveSelected='RV-001',liveZoom=14,liveTimer=null;
 const liveLabels={unconnected:'Sem rastreador',stale:'Posição desatualizada',moving:'Em movimento',stopped:'Parado · ignição ligada',parked:'Estacionado'};
 function activePanel(){const live=L.ensure(ops),positions=L.positions(ops),selected=positions.find(v=>v.vehicle.id===liveSelected)||positions[0];if(selected)liveSelected=selected.vehicle.id;return heading('VISIBILIDADE DA FROTA','Painel ativo. Cada carro, em contexto.','Mapa, vínculo, alertas e histórico de posição em um só lugar.',btn(liveTimer?'Pausar percurso de exemplo':'Reproduzir percurso de exemplo','live-play','primary'))+`<div class="notice live-notice"><div><strong>Telemetria demonstrativa · rastreador ainda não conectado</strong><p>Posições fictícias em Belo Horizonte. O percurso usa um relógio de exemplo de 25/01/2027; não representa localização atual de nenhuma pessoa.</p></div>${tag(liveTimer?'Reprodução em andamento':'Exemplo pausado',liveTimer?'green':'amber')}</div><div class="live-layout"><section class="panel map-panel"><div class="panel-head"><div><h2>Mapa da operação</h2><p>Clique no marcador ou no motorista para abrir o contexto.</p></div><div class="actions">${btn('−','live-zoom-out','', 'aria-label="Diminuir zoom"')}${btn('+','live-zoom-in','', 'aria-label="Aumentar zoom"')}</div></div>${liveMap()}<div class="map-footer"><span>Relógio do exemplo: ${esc(new Date(live.clock).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}))}</span><span>Mapa: <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">© OpenStreetMap contributors</a></span></div><p class="caption">Mapa-base online sujeito à disponibilidade. Se não carregar, os marcadores continuam sendo coordenadas de demonstração; nenhum dado real de GPS é enviado.</p><div class="actions gap">${btn('Avançar uma posição','live-step')}${btn('Simular 3 min sem sinal','live-stale')}${btn('Configurar alertas','live-settings')}</div></section><aside class="stack">${selected?liveVehicle(selected):'<div class="notice">Cadastre o primeiro carro para acompanhar a operação.</div>'}</aside></div><div class="stats gap">${stat('Carros com vínculo',String(positions.filter(p=>p.driver).length),'Somente veículos cadastrados nesta operação')}${stat('Posição recente no exemplo',String(positions.filter(p=>p.point&&p.status!=='stale').length),'Idade máxima de '+live.settings.staleSeconds+' s no relógio demonstrativo')}${stat('Sem posição atual',String(positions.filter(p=>!p.point||p.status==='stale').length),'Sem conexão ou com dado antigo')}${stat('Alertas de velocidade',String(live.events.length),'Limite de exemplo: '+live.settings.speedLimit+' km/h')}</div>${section('Todos os veículos','A lista também funciona quando o mapa está indisponível.')}<div class="live-vehicles">${positions.map(v=>`<button type="button" class="live-vehicle ${v.vehicle.id===liveSelected?'selected':''}" data-action="live-select" data-id="${v.vehicle.id}" aria-pressed="${v.vehicle.id===liveSelected}"><span class="avatar">${v.driver?initials(v.driver.name):'RV'}</span><span><strong>${esc(v.driver?.name||'Sem vínculo ativo')}</strong><small>${esc(v.vehicle.id+' · '+v.vehicle.model)}</small></span>${tag(liveLabels[v.status],v.status==='stale'||!v.point?'amber':'green')}</button>`).join('')}</div><div class="grid2 gap">${panel('Eventos de telemetria',live.events.length?live.events.slice(0,12).map(e=>row(esc(e.vehicleId),tag('Atenção','amber'),esc(e.text)+' · '+esc(e.at.slice(11,19))+' UTC')).join(''):'<p class="caption">Sem alerta no exemplo. O botão “Avançar uma posição” permite avaliar alertas e perda de sinal.</p>')}${panel('Conexão para a operação real',row('Provedor de rastreamento','A definir')+row('Origem da posição','Equipamento GPS / serviço contratado','Posição do veículo; não afirma localizar a pessoa fora do carro.')+row('Integração','Não conectada','Equipamento, API, servidor de eventos, vínculo por veículo e controle de acesso serão homologados.')+row('Idade do dado','Sempre visível','Sinal antigo permanece antigo; não tratar como presença em tempo real.'))}</div>`;}
 function liveMap(){const map=L.map(ops,liveSelected,liveZoom),trail=ops.live.points.filter(p=>p.vehicleId===liveSelected).slice(-30).map(p=>{const point=L.project(p.lat,p.lon,liveZoom);return (point.x-map.left).toFixed(1)+','+(point.y-map.top).toFixed(1);}).join(' ');return `<div class="map-surface" aria-label="Mapa geográfico com posições fictícias"><svg class="map-art" viewBox="0 0 ${map.width} ${map.height}" aria-hidden="true"><defs><pattern id="map-grid" width="65" height="65" patternUnits="userSpaceOnUse"><path d="M65 0H0V65" fill="none" stroke="#cfd9d2" stroke-width="1"/></pattern></defs><rect width="900" height="520" fill="#e8ede7"/><rect width="900" height="520" fill="url(#map-grid)"/>${map.tiles.map(t=>`<image href="${t.url}" x="${t.x}" y="${t.y}" width="256" height="256"/>`).join('')}<polyline points="${trail}" fill="none" stroke="#257b61" stroke-width="5" stroke-linejoin="round" stroke-dasharray="8 6" opacity=".75"/></svg><div class="map-label">POSIÇÕES DE EXEMPLO</div>${map.markers.filter(m=>m.x>=0&&m.x<=900&&m.y>=0&&m.y<=520).map(m=>`<button type="button" class="map-marker ${m.status==='stale'?'stale':''} ${m.vehicle.id===liveSelected?'selected':''}" style="left:${m.x/9}%;top:${m.y/5.2}%" data-action="live-select" data-id="${m.vehicle.id}" aria-label="Ver ${esc(m.driver?.name||m.vehicle.id)} no mapa"><span>▱</span><small>${esc(m.driver?.name.split(' ')[0]||m.vehicle.id)}</small></button>`).join('')}</div>`;}
 function liveVehicle(v){const p=v.point,d=v.driver,car=actual().snapshot.cars.find(c=>c.id===v.vehicle.id),contracts=d?K.driverDocuments(ops,d.id):[];return panel('Carro e motorista',`<div class="vehicle-line"><span class="vehicle-symbol" aria-hidden="true">▱</span><div><h3>${esc(v.vehicle.model)}</h3><small>${esc(v.vehicle.id+' · '+v.vehicle.plate)}</small></div></div>`+row('Motorista',esc(d?.name||'Sem motorista ativo'))+row('Estado da posição',tag(liveLabels[v.status],v.status==='stale'||!p?'amber':'green'))+(p?row('Última posição',num(v.age)+' s atrás','Idade no relógio demonstrativo, não no relógio atual.')+`<div class="telemetry-grid">${[['Velocidade',num(p.speed)+' km/h'],['Ignição',p.ignition?'Ligada':'Desligada'],['Hodômetro',num(p.odometer)+' km'],['Combustível',num(p.fuel)+'%'],['Bateria',num(p.battery)+' V'],['Precisão GPS','±'+num(p.accuracy)+' m']].map(([label,value])=>`<div><small>${label}</small><strong>${value}</strong></div>`).join('')}</div>`+row('Coordenadas',p.lat.toFixed(5)+', '+p.lon.toFixed(5),'Posição válida de demonstração · '+p.fixTime.slice(11,19)+' UTC'):'<p class="notice amber">Este carro ainda não possui posição de exemplo. Selecione “Avançar uma posição” para testar.</p>')+row('Aluguel em aberto',d?cash(ops.charges.filter(c=>c.driverId===d.id&&c.status!=='paid').reduce((s,c)=>s+R.currentChargeBalance(ops,c),0)):'—')+row('Contratos do perfil',contracts.length+' documento(s)',contracts.map(c=>c.statusLabel).join(' · '))+row('Vistoria mais recente',d?(I.forDriver(ops,d.id)[0]?inspectionStatuses[I.forDriver(ops,d.id)[0].status]:'Não registrada'):'Sem vínculo')+row('Dívida do veículo',car?cash(car.debt):'Sem fechamento')+row('Próxima revisão',num(Math.max(0,v.vehicle.nextKm-v.vehicle.km))+' km')+`<div class="actions gap">${d?btn('Ficha do motorista','driver-detail','',`data-id="${d.id}"`):''}${btn('Contratos','go-lawyer')}${btn('Vistorias','inspection-admin')}${btn('Financeiro','go-finance')}${btn('Histórico de posições','live-history','',`data-id="${v.vehicle.id}"`)}</div>`);}
 function liveAction(action,e){if(!action.startsWith('live-'))return false;if(action==='live-history'){const points=ops.live.points.filter(p=>p.vehicleId===e.dataset.id).slice().reverse();open('Histórico de posições · '+e.dataset.id,table(['Horário da posição','Lat / lon','Velocidade','GPS'],points.map(p=>`<tr><td>${esc(p.fixTime)}</td><td>${p.lat.toFixed(5)}, ${p.lon.toFixed(5)}</td><td>${num(p.speed)} km/h</td><td>±${num(p.accuracy)} m</td></tr>`).join(''))+'<p class="caption">Amostras fictícias da reprodução. Horário da posição é preservado, mesmo após perder sinal.</p>');return true;}if(action==='live-select')liveSelected=e.dataset.id;else if(action==='live-step')L.replay(ops,liveSelected);else if(action==='live-stale')L.advanceClock(ops,180);else if(action==='live-zoom-in')liveZoom=Math.min(16,liveZoom+1);else if(action==='live-zoom-out')liveZoom=Math.max(12,liveZoom-1);else if(action==='live-play'){if(liveTimer){clearInterval(liveTimer);liveTimer=null;}else{L.replay(ops);liveTimer=setInterval(()=>{if(page!=='live'||mode!=='admin'){clearInterval(liveTimer);liveTimer=null;return;}L.replay(ops);render();persist();},5000);}}else if(action==='live-settings'){open('Limite de alerta · demonstração',`<form id="live-settings-form">${input('speedLimit','Velocidade para alerta · km/h',ops.live.settings.speedLimit,'type="number" min="1" max="180" required')}${input('staleSeconds','Posição antiga após · segundos',ops.live.settings.staleSeconds,'type="number" min="15" max="3600" required')}<p class="caption">Configuração do exemplo. Não interpreta limite legal da via nem comanda o carro.</p><div class="form-actions"><button class="btn primary" type="submit">Salvar limites do exemplo</button></div></form>`);return true;}else return false;render();persist();if(action==='live-select'){const selected=L.positions(ops).find(v=>v.vehicle.id===liveSelected);if(selected)open('Motorista e veículo · demonstração',liveVehicle(selected));}return true;}
 function liveSubmit(form,f){if(form.id!=='live-settings-form')return false;const speedLimit=Number(f.get('speedLimit')),staleSeconds=Number(f.get('staleSeconds'));if(!Number.isFinite(speedLimit)||speedLimit<1||speedLimit>180||!Number.isFinite(staleSeconds)||staleSeconds<15||staleSeconds>3600)throw new RangeError('Revise os limites.');ops.live.settings={speedLimit,staleSeconds};close();render();persist();toast('Limites de alerta atualizados no exemplo.');return true;}
